const wh = $input.first().json;
const body = (wh.resume_id !== undefined) ? wh : (wh.body || wh);

if (!body.resume_id || !body.callback_url) {
  throw new Error('Dados em falta: resume_id=' + body.resume_id + ' callback_url=' + body.callback_url);
}

const cvText = String(body.cv_text || '').slice(0, 6000);
const prompt =
  'Analisa o seguinte curriculo e responde APENAS com JSON valido com estes campos: ' +
  'score (inteiro 0-100), skills (lista de strings), summary (string), experience (string), ' +
  'education (string), languages (string), feedback (string).\n\nCurriculo:\n' + cvText;

return [{ json: {
  resume_id:    body.resume_id,
  callback_url: body.callback_url,
  ollamaModel:  'llama3.2:1b',
  ollamaStream: false,
  ollamaFormat: 'json',
  ollamaPrompt: prompt,
}}];

const ollamaResp = $input.first().json;
const prev = $('Preparar Pedido').first().json;

function toStr(val) {
  if (val == null) return '';
  if (typeof val === 'string') return val.trim();
  if (Array.isArray(val)) return val.map(i => (typeof i === 'object' ? JSON.stringify(i) : String(i))).join(', ');
  if (typeof val === 'object') return Object.values(val).filter(Boolean).join(' | ') || JSON.stringify(val);
  return String(val);
}

let analysis = {};
try {
  const raw = String(ollamaResp.response || '{}');
  analysis = JSON.parse(raw.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim());
} catch (_) {}

return [{ json: {
  resume_id:    prev.resume_id,
  callback_url: prev.callback_url,
  score:      Math.min(100, Math.max(0, parseFloat(analysis.score) || 50)),
  skills:     Array.isArray(analysis.skills) ? analysis.skills.map(s => (typeof s === 'object' ? JSON.stringify(s) : String(s))).join(', ') : toStr(analysis.skills) || 'Nao identificadas',
  summary:    toStr(analysis.summary)    || 'Resumo nao disponivel',
  experience: toStr(analysis.experience) || 'Nao especificada',
  education:  toStr(analysis.education)  || 'Nao especificada',
  languages:  toStr(analysis.languages)  || 'Nao identificados',
  feedback:   toStr(analysis.feedback)   || 'Analise concluida.',
}}];
